import{_ as r,o as e,c as d,a5 as o}from"./chunks/framework.DJo0M80U.js";const i=JSON.parse('{"title":"Vue 3 响应式 Map 全攻略","description":"方案清单 场景 推荐方案 代码示例 代价 / 注意点 A. 只关心行的增删 例如列表渲染组件 继续用 Array.from(map.values()) ts const rows computed(() \\\\ Array.from(openOrderData.values()))。","frontmatter":{"title":"Vue 3 响应式 Map 全攻略","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"方案清单 场景 推荐方案 代码示例 代价 / 注意点 A. 只关心行的增删 例如列表渲染组件 继续用 Array.from(map.values()) ts const rows computed(() \\\\ Array.from(openOrderData.values()))。","sidebarWeight":140,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/响应式问题/Vue 3 响应式 Map 全攻略/Vue 3 响应式 Map 全攻略.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/Vue 3 响应式 Map 全攻略/Vue 3 响应式 Map 全攻略.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/Vue 3 响应式 Map 全攻略/Vue 3 响应式 Map 全攻略.md"}'),a={name:"posts/Vue系统教程/03-响应式与组合式 API/Vue 3 响应式 Map 全攻略/Vue 3 响应式 Map 全攻略.md"};function s(n,t,p,g,u,c){return e(),d("div",null,[...t[0]||(t[0]=[o('<div><h1 id="vue-3-响应式-map-全攻略" tabindex="-1">Vue 3 响应式 Map 全攻略 <a class="header-anchor" href="#vue-3-响应式-map-全攻略" aria-label="Permalink to &quot;Vue 3 响应式 Map 全攻略&quot;">​</a></h1><blockquote><p>本节目标：理解“Vue 3 响应式 Map 全攻略”的核心思路，并能把它用于实际开发或面试表达。 <strong>方案清单</strong></p></blockquote><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>场景</strong></td><td><strong>推荐方案</strong></td><td><strong>代码示例</strong></td><td><strong>代价 / 注意点</strong></td></tr><tr><td><strong>A. 只关心行的增删</strong></td><td></td><td></td><td></td></tr><tr><td>例如列表渲染组件</td><td>继续用 Array.from(map.values())</td><td>ts const rows = computed(() =&gt; Array.from(openOrderData.values()))</td><td>性能好；行内部更新不会触发。</td></tr><tr><td><strong>B. 需要行内容一有变动就刷新 UI</strong></td><td>在 computed 里<strong>显式展开</strong>行对象（最简）</td><td>ts const rows = computed(() =&gt; Array.from(openOrderData.values()).map(r =&gt; ({ ...r })))</td><td>每次计算都会浅拷贝；Map 很大时有额外 GC 压力。</td></tr><tr><td></td><td>或：用 watchEffect 深度读取指定字段</td><td>ts watchEffect(() =&gt; { openOrderData.forEach(r =&gt; { void r.price; void r.qty }) })</td><td>手动列出依赖字段，可按需优化。</td></tr><tr><td><strong>C. 只关心某些字段</strong></td><td></td><td></td><td></td></tr><tr><td>避免拷贝整个行</td><td>把 <strong>关键字段</strong>映射成派生数组</td><td>ts const prices = computed(() =&gt; [...openOrderData.values()].map(r =&gt; r.price))</td><td>依赖量小，但要同时维护行和字段数组的关系。</td></tr><tr><td><strong>D. 性能极敏感</strong></td><td></td><td></td><td></td></tr><tr><td>且行对象巨大</td><td>1️⃣ 给行包一层 ref（行变动时用 rowRef.value = {…}）</td><td></td><td></td></tr><tr><td>2️⃣ 或把 Map ➜ Reactive Record（普通对象）</td><td>ts const rowRef = ref&lt;Row&gt;() openOrderData.set(id, rowRef)</td><td>代码更啰嗦，牺牲一点语义清晰度换性能可控。</td><td></td></tr></tbody></table><p><strong>4. 常见坑 &amp; 对策</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>症状</strong></td><td><strong>根因</strong></td><td><strong>修复思路</strong></td></tr><tr><td>行对象属性变了，UI 不更新</td><td>没有依赖收集到具体属性</td><td>方案 B / C / D</td></tr><tr><td>Object.assign 后依旧不触发</td><td>被赋值的字段值相同或没收集依赖</td><td>确认字段真的变化；改用新对象引用</td></tr><tr><td>替换整行也不触发</td><td>直接 map.set(key, newRow) 正常会触发；若没触发，检查 newRow === oldRow</td><td>确保提供全新引用</td></tr><tr><td>大量条目更新造成卡顿</td><td>computed 每次做浅拷贝</td><td>改成 watchEffect 精准追踪 (void r.xxx) 或用 ref 包装行</td></tr></tbody></table><p><strong>5. 代码片段模板（复制即用）</strong><strong>5.1 统一封装更新函数</strong> function upsertRow(map: Map&lt;number, Row&gt;, row: Row) { const exist = map.get(row.id); if (exist) { // ⚠️ 优先替换引用，触发次数最少 map.set(row.id, { ...exist, ...row }); } else { map.set(row.id, row); } }</p><p>5.2 带依赖收集的 computed // 收集全部列（适合表格场景） const tableRows = computed(() =&gt; Array.from(openOrderData.values()).map(r =&gt; ({ ...r })) );</p><p>5.3 精准监听字段（大数据量场景） watchEffect(() =&gt; { openOrderData.forEach(r =&gt; { // 只读关键字段，Vue 会对这些字段建立依赖 void r.status; void r.lastPrice; }); });</p><p><strong>6. 结语</strong></p><ul><li><strong>先想依赖</strong>、再写 computed —— 牢记 Vue 只在 <em>你读取的地方</em> 建立追踪。</li><li><strong>Map ≠ 普通对象</strong>：Vue 不会帮你深拷贝或深监听，你要手动“触摸”字段。</li><li><strong>三板斧</strong>： <ol><li><em>确认场景</em>（只关心结构？还是行内容？）</li><li><em>选方案</em>（A/B/C/D）</li><li><em>验证依赖</em>（console.log + Vue DevTools）</li></ol></li></ul><p>有了这份教程，下次遇到“Map 里改了数据 UI 不刷”的问题，只需按照 <strong>判断流程 → 方案清单</strong> 两步走，很快就能定位并解决💪。祝编码顺利！</p></div>',1)])])}const m=r(a,[["render",s]]);export{i as __pageData,m as default};
